select id as id, brand_name as brandName, brand_place as brandPlace, create_name as createName, create_user as createUser, create_time as createTime, update_name as updateName, update_user as updateUser, update_time as updateTime from ytsafety_brand_vehicle
del_flag = 0
AND brand_name LIKE CONCAT('%', #{query.brandName}, '%')
AND brand_place LIKE CONCAT('%', #{query.brandPlace}, '%')
AND create_name LIKE CONCAT('%', #{query.createName}, '%')
AND update_name LIKE CONCAT('%', #{query.updateName}, '%')
AND create_time >= #{query.createTimeStart}
AND create_time <= #{query.createTimeEnd}
AND update_time >= #{query.updateTimeStart}
AND update_time <= #{query.updateTimeEnd}
order by update_time desc

